        "sources": {
          "IK-1870868:L206:span1": {
            "text": "The appellant is the tenant of a building in Delhi having been inducted into possession by the respondent- landlord under a letting of May 19, 1954",
            "document_id": "1870868",
            "url": "https://indiankanoon.org/doc/1870868/",
            "semantic_stage": "PRE_TARGET_RECORD",
            "prospective_availability": "RETROSPECTIVELY_RECONSTRUCTED_PRE_TARGET"
          },
          "IK-1870868:L207:span2": {
            "text": "The landlord had been receiving rent from the tenant until the time he filed a petition for eviction (1967)",
            "document_id": "1870868",
            "url": "https://indiankanoon.org/doc/1870868/",
            "semantic_stage": "PRE_TARGET_RECORD",
            "prospective_availability": "RETROSPECTIVELY_RECONSTRUCTED_PRE_TARGET"
          },
          "IK-1870868:L208:span3": {
            "text": "The eviction petition set out two grounds out of the many specified in cite21†s. 14 of the Rent Act, viz.,unauthorized sub-letting of a portion of the premises and possession, by the tenant, of alternative accommodation.",
            "document_id": "1870868",
            "url": "https://indiankanoon.org/doc/1870868/",
            "semantic_stage": "PRE_TARGET_RECORD",
            "prospective_availability": "RETROSPECTIVELY_RECONSTRUCTED_PRE_TARGET"
          },
          "IK-1870868:L212:span4": {
            "text": "The Rent Controller, at the floor level, ordered eviction and the Appellate Tribunal affirmed it, upholding the vice of sub-letting without consent of the landlord in the manner specified in cite23†s. 14(1)(b)",
            "document_id": "1870868",
            "url": "https://indiankanoon.org/doc/1870868/",
            "semantic_stage": "PRIOR_COURT_FINDING",
            "prospective_availability": "RETROSPECTIVELY_RECONSTRUCTED_PRE_TARGET"
          },
          "IK-1870868:L241:span5": {
            "text": "The Tribunal studied the terms of the rent deed, Exhibit AW 3/1 and held that there was an express condition against sub-letting",
            "document_id": "1870868",
            "url": "https://indiankanoon.org/doc/1870868/",
            "semantic_stage": "PRIOR_COURT_FINDING",
            "prospective_availability": "RETROSPECTIVELY_RECONSTRUCTED_PRE_TARGET"
          }
